const ctl = new Int32Array(sab, 0, 2);         // [head, tail] in shared memory
const data = new Int32Array(sab, 8, CAP);
function push(v: number): boolean {             // producer worker
  const t = Atomics.load(ctl, 1);
  if (t - Atomics.load(ctl, 0) === CAP) return false;   // full: apply policy
  data[t % CAP] = v;                                    // payload first...
  Atomics.store(ctl, 1, t + 1);                         // ...then publish the ticket
  return true;
}
